function calculate_shipping( $package = Array() ) {
    $shipping_tax_class = get_option('woocommerce_shipping_tax_class');
    $rate = [
      'id'      => $this->get_rate_id(),
      'label'   => $this->get_option('title'),
      'cost'    => $this->get_option('fee'),
      'package' => $package,
      'tax_class' => $shipping_tax_class,
    ];

    $ignored_classes = $this->get_option('ignore_shipping_classes', []);
    if ( is_array( $ignored_classes ) && ! empty( $ignored_classes ) ) {
      $found_shipping_classes = $this->find_shipping_classes_for_package($package);

      foreach ($found_shipping_classes as $found_class) {
        if (in_array($found_class, $ignored_classes)) {
          return;
        }
      }
    }

    $cart_total_weight = WC()->cart->cart_contents_weight;
    if (get_option('woocommerce_weight_unit') == 'g') {
        $cart_total_weight /= 1000;
    }

    switch (get_option( 'woocommerce_dimension_unit' )) {
      case 'm':
        $unit_multiplayer = 0.01;
        break;
      case 'mm':
        $unit_multiplayer = 10;
        break;
      default:
        $unit_multiplayer = 1;
    }

    $maximum_weight_locker = $this->get_option('maximum_weight') ? $this->get_option('maximum_weight') : 30;
    $manimum_weight_locker = $this->get_option('minimum_weight') ? $this->get_option('minimum_weight') : 0;
		$maximum_weight_pickup = min($maximum_weight_locker, 10);
		$minimum_weight_pickup = $manimum_weight_locker;

    // Locker internal max dimensions (cm by default)
    $venipak_box_dims = [
      61 * $unit_multiplayer,
      39.5 * $unit_multiplayer,
      41 * $unit_multiplayer,
    ];
    sort($venipak_box_dims); // allow any orientation by comparing sorted dims
    $venipak_max_volume = array_product($venipak_box_dims);

    $is_valid_for_locker = true;
    $is_valid_for_pickup = true;
    $total_cart_volume = 0;
    $dedicated_packs = 0;
    foreach ( WC()->cart->get_cart() as $cart_item ) {
      $product = $cart_item['data']; // Directly use the product data

			if ($product->is_type('variation')) {
				$product = new WC_Product_Variation($cart_item['variation_id']);
			}
      $product_dimensions = [
        (float)$product->get_length() ?: 0,
        (float)$product->get_width() ?: 0,
        (float)$product->get_height() ?: 0,
      ];
      sort($product_dimensions);
      $total_cart_volume += ($product_dimensions[0] * $product_dimensions[1] * $product_dimensions[2]) * $cart_item['quantity'];
      if (
        $product_dimensions[0] > $venipak_box_dims[0] ||
        $product_dimensions[1] > $venipak_box_dims[1] ||
        $product_dimensions[2] > $venipak_box_dims[2]
      ) {
        $is_valid_for_locker = false;
      }
      $product_min_age = $product->get_meta('shopup_venipak_shipping_min_age');
      if ($product_min_age > 0) {
        $is_valid_for_locker = false;
        $is_valid_for_pickup = false;
      }
      $product_packs = $product->get_meta('_venipak_total_shipments', true) ?: $product->get_meta('_omnivalt_total_shipments', true);
      $dedicated_packs += $product_packs ?: 0;
    }
    if ($dedicated_packs > 1) {
      $is_valid_for_locker = false;
      $is_valid_for_pickup = false;
    }
    if ($dedicated_packs === 1 && count(WC()->cart->get_cart()) > 1) {
      $is_valid_for_locker = false;
      $is_valid_for_pickup = false;
    }
    if ($cart_total_weight > $maximum_weight_locker || ($manimum_weight_locker > 0 && $cart_total_weight <= $manimum_weight_locker)) {
      $is_valid_for_locker = false;
    }
    if ($cart_total_weight > $maximum_weight_pickup || ($minimum_weight_pickup > 0 && $cart_total_weight <= $minimum_weight_pickup)) {
      $is_valid_for_pickup = false;
    }
    if ($total_cart_volume > $venipak_max_volume) {
      $is_valid_for_locker = false;
    }

    $venipak_shipping_settings = get_option('shopup_venipak_shipping_settings');
    if ($venipak_shipping_settings) {
      $pickup_type = $venipak_shipping_settings['shopup_venipak_shipping_field_pickuptype'];
    } else {
      $pickup_type = 'all';
    }

    if (
      ($pickup_type == 1 && $is_valid_for_pickup) ||
      ($pickup_type == 3 && $is_valid_for_locker) ||
      ($pickup_type == 'all' && ($is_valid_for_locker || $is_valid_for_pickup))
    ) {
      $this->free_shipping_check( $package, $rate );
      $this->add_rate( $rate );
    }
  }

